// SecurityConfig.java
@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            // Require HTTPS for all requests
            .requiresChannel(channel -> channel
                .anyRequest().requiresSecure())

            // OAuth2 login with PKCE
            .oauth2Login(oauth2 -> oauth2
                .authorizationEndpoint(authorization -> authorization
                    .authorizationRequestResolver(pkceAuthorizationRequestResolver()))
                .redirectionEndpoint(redirection -> redirection
                    .baseUri("/oauth2/callback/*")))

            // OAuth2 resource server
            .oauth2ResourceServer(oauth2 -> oauth2
                .jwt(jwt -> jwt
                    .jwtAuthenticationConverter(jwtAuthenticationConverter())))

            // Endpoint authorization
            .authorizeHttpRequests(authorize -> authorize
                .requestMatchers("/actuator/health").permitAll()
                .requestMatchers("/api/transactions/**").hasAuthority("SCOPE_transactions:write")
                .requestMatchers("/api/accounts/**").hasAuthority("SCOPE_accounts:read")
                .anyRequest().authenticated());

        return http.build();
    }

    @Bean
    public OAuth2AuthorizationRequestResolver pkceAuthorizationRequestResolver() {
        DefaultOAuth2AuthorizationRequestResolver resolver = 
            new DefaultOAuth2AuthorizationRequestResolver(
                clientRegistrationRepository, "/oauth2/authorization");
        resolver.setAuthorizationRequestCustomizer(
            OAuth2AuthorizationRequestCustomizers.withPkce());
        return resolver;
    }
}

# nginx.conf
user nginx;
worker_processes auto;
error_log /var/log/nginx/error.log warn;
pid /var/run/nginx.pid;

events {
    worker_connections 1024;
}

http {
    # Security headers
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;
    add_header X-Frame-Options "DENY" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-XSS-Protection "1; mode=block" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;

    # TLS configuration
    ssl_protocols TLSv1.3 TLSv1.2;
    ssl_ciphers 'ECDHE-RSA-AES256-GCM-SHA384:ECDHE-RSA-AES128-GCM-SHA256';
    ssl_prefer_server_ciphers off;

    # SSL session configuration
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 10m;
    ssl_session_tickets off;

    # OCSP stapling
    ssl_stapling on;
    ssl_stapling_verify on;
    ssl_trusted_certificate /etc/nginx/certs/ca-chain.pem;
    resolver 8.8.8.8 8.8.4.4 valid=300s;
    resolver_timeout 5s;

    # Disable compression
    gzip off;

    server {
        listen 443 ssl http2;
        server_name api.bank.example.com;

        # TLS certificates
        ssl_certificate /etc/nginx/certs/server-cert.pem;
        ssl_certificate_key /etc/nginx/certs/server-key.pem;

        # Client certificate authentication (mTLS)
        ssl_client_certificate /etc/nginx/certs/client-ca.pem;
        ssl_verify_client on;
        ssl_verify_depth 2;

        # CRL for revocation checking
        ssl_crl /etc/nginx/certs/crl.pem;

        # Proxy to backend
        location / {
            proxy_pass https://backend:8443;
            proxy_ssl_certificate /etc/nginx/certs/proxy-client-cert.pem;
            proxy_ssl_certificate_key /etc/nginx/certs/proxy-client-key.pem;
            proxy_ssl_trusted_certificate /etc/nginx/certs/backend-ca.pem;
            proxy_ssl_verify on;
            proxy_ssl_verify_depth 2;

            # Pass client certificate info to backend
            proxy_set_header X-SSL-Client-Cert $ssl_client_cert;
            proxy_set_header X-SSL-Client-S-DN $ssl_client_s_dn;
            proxy_set_header X-SSL-Client-Verify $ssl_client_verify;
        }

        # Health check endpoint (no client cert required)
        location /health {
            ssl_verify_client optional;
            return 200 "OK\n";
            add_header Content-Type text/plain;
        }
    }

    # Redirect HTTP to HTTPS
    server {
        listen 80;
        server_name api.bank.example.com;
        return 301 https://$server_name$request_uri;
    }
}

// AuthorizationServerConfig.java
@Configuration
public class AuthorizationServerConfig {

    @Bean
    @Order(1)
    public SecurityFilterChain authorizationServerSecurityFilterChain(HttpSecurity http) 
            throws Exception {
        OAuth2AuthorizationServerConfiguration.applyDefaultSecurity(http);

        http.getConfigurer(OAuth2AuthorizationServerConfigurer.class)
            .oidc(Customizer.withDefaults());

        http
            .exceptionHandling(exceptions -> exceptions
                .defaultAuthenticationEntryPointFor(
                    new LoginUrlAuthenticationEntryPoint("/login"),
                    new MediaTypeRequestMatcher(MediaType.TEXT_HTML)))
            .oauth2ResourceServer(oauth2 -> oauth2
                .jwt(Customizer.withDefaults()));

        return http.build();
    }

    @Bean
    public RegisteredClientRepository registeredClientRepository() {
        RegisteredClient bankingApp = RegisteredClient.withId(UUID.randomUUID().toString())
            .clientId("banking-app")
            .clientSecret("{bcrypt}" + passwordEncoder().encode("secret"))
            .clientAuthenticationMethod(ClientAuthenticationMethod.CLIENT_SECRET_POST)
            .authorizationGrantType(AuthorizationGrantType.AUTHORIZATION_CODE)
            .authorizationGrantType(AuthorizationGrantType.REFRESH_TOKEN)
            .redirectUri("https://app.bank.example.com/oauth2/callback")
            .scope(OidcScopes.OPENID)
            .scope(OidcScopes.PROFILE)
            .scope("transactions:read")
            .scope("transactions:write")
            .scope("accounts:read")
            .clientSettings(ClientSettings.builder()
                .requireAuthorizationConsent(true)
                .requireProofKey(true)  // Require PKCE
                .build())
            .tokenSettings(TokenSettings.builder()
                .accessTokenTimeToLive(Duration.ofMinutes(15))
                .refreshTokenTimeToLive(Duration.ofDays(1))
                .reuseRefreshTokens(false)  // Refresh token rotation
                .build())
            .build();

        return new InMemoryRegisteredClientRepository(bankingApp);
    }

    @Bean
    public JWKSource<SecurityContext> jwkSource() {
        KeyPair keyPair = generateRsaKey();
        RSAPublicKey publicKey = (RSAPublicKey) keyPair.getPublic();
        RSAPrivateKey privateKey = (RSAPrivateKey) keyPair.getPrivate();
        RSAKey rsaKey = new RSAKey.Builder(publicKey)
            .privateKey(privateKey)
            .keyID(UUID.randomUUID().toString())
            .build();
        JWKSet jwkSet = new JWKSet(rsaKey);
        return new ImmutableJWKSet<>(jwkSet);
    }

    private static KeyPair generateRsaKey() {
        KeyPair keyPair;
        try {
            KeyPairGenerator keyPairGenerator = KeyPairGenerator.getInstance("RSA");
            keyPairGenerator.initialize(3072);  // RSA-3072 for quantum resistance
            keyPair = keyPairGenerator.generateKeyPair();
        } catch (Exception ex) {
            throw new IllegalStateException(ex);
        }
        return keyPair;
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder(12);
    }
}

// RedirectUriValidator.java
@Component
public class RedirectUriValidator {

    private static final Set<String> ALLOWED_REDIRECT_URIS = Set.of(
        "https://app.bank.example.com/oauth2/callback",
        "https://mobile.bank.example.com/oauth2/callback"
    );

    public boolean isValid(String redirectUri) {
        // Exact string matching only - no wildcards, no pattern matching
        return ALLOWED_REDIRECT_URIS.contains(redirectUri);
    }

    public void validate(String redirectUri) {
        if (!isValid(redirectUri)) {
            throw new OAuth2AuthenticationException(
                new OAuth2Error(OAuth2ErrorCodes.INVALID_REQUEST, 
                    "Invalid redirect_uri", null));
        }
    }
}

// PKCEValidator.java
@Component
public class PKCEValidator {

    public void validateAuthorizationRequest(OAuth2AuthorizationRequest request) {
        String codeChallenge = request.getAttribute("code_challenge");
        String codeChallengeMethod = request.getAttribute("code_challenge_method");

        if (codeChallenge == null || codeChallengeMethod == null) {
            throw new OAuth2AuthenticationException(
                new OAuth2Error(OAuth2ErrorCodes.INVALID_REQUEST,
                    "PKCE is required: code_challenge and code_challenge_method must be provided",
                    null));
        }

        if (!"S256".equals(codeChallengeMethod)) {
            throw new OAuth2AuthenticationException(
                new OAuth2Error(OAuth2ErrorCodes.INVALID_REQUEST,
                    "Only S256 code_challenge_method is supported",
                    null));
        }
    }

    public void validateTokenRequest(String codeVerifier, String codeChallenge) {
        if (codeVerifier == null) {
            throw new OAuth2AuthenticationException(
                new OAuth2Error(OAuth2ErrorCodes.INVALID_REQUEST,
                    "code_verifier is required",
                    null));
        }

        // Verify code_verifier matches code_challenge
        String computedChallenge = Base64.getUrlEncoder()
            .withoutPadding()
            .encodeToString(
                MessageDigest.getInstance("SHA-256")
                    .digest(codeVerifier.getBytes(StandardCharsets.US_ASCII)));

        if (!computedChallenge.equals(codeChallenge)) {
            throw new OAuth2AuthenticationException(
                new OAuth2Error(OAuth2ErrorCodes.INVALID_GRANT,
                    "Invalid code_verifier",
                    null));
        }
    }
}
